/// <summary>
/// MPJ_30779_PaymentPlus
/// Class <c>METAzureADTokenContract</c> is used for AAD token JSON deserialization
/// </summary>
[DataContract]
public class METAzureADTokenContract
{
    private str tokenType;
    private int expiresIn;
    private int extExpiresIn;
    private str accessToken;

}

Method.Source:
[DataMember('token_type')]
public str parmTokenType(str _tokenType = tokenType)
{
    tokenType = _tokenType;
    return tokenType;
}

[DataMember('expires_in')]
public int parmExpiresIn(int _expiresIn = expiresIn)
{
    expiresIn = _expiresIn;
    return expiresIn;
}

[DataMember('ext_expires_in')]
public int parmExtExpiresIn(int _extExpiresIn = extExpiresIn)
{
    extExpiresIn = _extExpiresIn;
    return extExpiresIn;
}

[DataMember('access_token')]
public str parmAccessToken(str _accessToken = accessToken)
{
    accessToken = _accessToken;
    return accessToken;
}

/// <summary>
/// creates a new instance of the Azure AD Token contract
/// </summary>
/// <returns>returns a Azure AD Token contract</returns>
public static METAzureADTokenContract construct()
{
    return new METAzureADTokenContract();
}
